div.script:
var RPC = function(model, method, kwargs) {
    return fetch("/web/dataset/call_kw", {
        method: "POST",
        headers: {"Content-Type": "application/json", "X-Requested-With": "XMLHttpRequest"},
        body: JSON.stringify({jsonrpc: "2.0", method: "call",
            params: {model: model, method: method, args: [], kwargs: kwargs || {}}}),
    }).then(function(r) { return r.json(); }).then(function(j) {
        if (j.error) { throw new Error((j.error.data && j.error.data.message) || j.error.message); }
        return j.result;
    });
};
var root = document.getElementById("odk-scan-root");
var state = root.querySelector("#state");
var logBox = root.querySelector("#log");
var logCount = 0;
var current = null;
var setState = function(t, cls) { state.textContent = t; state.className = "pill " + (cls || "err"); };

RPC("odk.scan", "act_warehouses", {}).then(function(ws) {
    var fill = function(sel, defIdx) {
        sel.innerHTML = "";
        ws.forEach(function(w) {
            var o = document.createElement("option");
            o.value = w.id; o.textContent = w.name + " (" + w.code + ")";
            sel.appendChild(o);
        });
        if (ws.length > defIdx) sel.selectedIndex = defIdx;
    };
    fill(root.querySelector("#wh-from"), 0);
    fill(root.querySelector("#wh-to"), Math.min(1, ws.length - 1));
}).catch(function(e) { setState("仓库加载失败：" + e.message); });

root.querySelector("#scan-input").addEventListener("keydown", function(ev) {
    if (ev.key !== "Enter") return;
    var code = ev.target.value.trim();
    if (!code) return;
    setState("识别中…");
    RPC("odk.scan", "act_lookup", {barcode: code}).then(function(item) {
        if (!item || !item.id) {
            setState("未识别");
            current = null;
            root.querySelector("#item-box").style.display = "none";
            root.querySelector("#submit-btn").disabled = true;
            return;
        }
        current = item;
        setState("已识别", "ok");
        root.querySelector("#item-box").style.display = "block";
        root.querySelector("#item-info").innerHTML =
            "<b>" + item.code + "</b> " + item.name + "<br/>单位：" + item.uom + " · 条码 " + item.barcode;
        root.querySelector("#submit-btn").disabled = false;
        var qty = root.querySelector("#qty");
        qty.focus(); qty.select();
    }).catch(function(e) { setState("识别失败：" + e.message); });
});

root.querySelector("#submit-btn").addEventListener("click", function() {
    var btn = this;
    if (!current) return;
    var qty = parseFloat(root.querySelector("#qty").value || "0");
    var fromId = root.querySelector("#wh-from").value;
    var toId = root.querySelector("#wh-to").value;
    var foRef = root.querySelector("#fo-ref").value.trim();
    if (qty <= 0) { setState("数量必须大于 0"); return; }
    btn.disabled = true; btn.textContent = "提交中…";
    RPC("odk.scan", "act_transfer", {
        barcode: current.code || current.barcode,
        qty: qty, from_id: parseInt(fromId), to_id: parseInt(toId), fo_ref: foRef,
    }).then(function(res) {
        logCount++;
        if (logCount === 1) logBox.innerHTML = "";
        var d = new Date();
        var row = document.createElement("div");
        row.className = "log";
        row.innerHTML = "<b>" + res.name + "</b> 已过账 · " + current.code + " ×" + qty + (foRef ? " · " + foRef : "");
        logBox.insertBefore(row, logBox.firstChild);
        setState("出入库成功：" + res.name, "ok");
        var si = root.querySelector("#scan-input");
        si.value = ""; si.focus();
        current = null;
        root.querySelector("#item-box").style.display = "none";
        btn.disabled = true;
    }).catch(function(e) {
        setState("提交失败：" + e.message);
        btn.disabled = false;
    }).then(function() { btn.textContent = "提交出入库"; });
});
root.querySelector("#scan-input").focus();
